function mount(page){var i=+page.dataset.page,p=pageState(i),inst=p&&instFor(p);if(!p||!inst)return;defaults(p);if(mounted[p.id]&&mounted[p.id].page===page){render(p);return}var web=page.querySelector('.df-webgl'),body=page.querySelector('.df-sketch-body');if(!web||!body)return;var ui=document.createElement('canvas');ui.className='dcsp-ui-canvas';web.appendChild(ui);var panel=document.createElement('div');panel.innerHTML=panelHtml(p);body.insertBefore(panel.firstChild,web.nextSibling);mounted[p.id]={page:page,ui:ui,tool:'orbit',pendingText:''};bindCanvas(p);wirePanel(p);interceptCore(page,p);render(p);updateInspector(p);updateLists(p);updateProjectColors(p);enhanceColor(p)}
