function hexRgb(h){h=String(h||'#dc2626').replace('#','');if(h.length===3)h=h.replace(/(.)/g,'$1$1');var n=parseInt(h,16);return isFinite(n)?[(n>>16)&255,(n>>8)&255,n&255]:[220,38,38]}function rgbHex(r,g,b){return'#'+[r,g,b].map(function(n){return clamp(Math.round(Number(n)||0),0,255).toString(16).padStart(2,'0')}).join('')}function shade(h,f){var a=hexRgb(h);return rgbHex(a[0]+(f<0?a[0]:255-a[0])*Math.abs(f),a[1]+(f<0?a[1]:255-a[1])*Math.abs(f),a[2]+(f<0?a[2]:255-a[2])*Math.abs(f))}
function enhanceColor(p){var m=mounted[p.id],q=defaults(p),custom=m&&m.page.querySelector('.df-color-panel[data-color-panel="custom"]');if(!custom||custom.querySelector('.dcsp-color-plus'))return;var rgb=hexRgb(p.drawColor),d=document.createElement('div');d.className='dcsp-color-plus';d.innerHTML='<b>'+T('RGB / shades','RGB / تدرجات')+'</b><div class="dcsp-row"><label>R<input type="number" min="0" max="255" data-rgb="0" value="'+rgb[0]+'"></label><label>G<input type="number" min="0" max="255" data-rgb="1" value="'+rgb[1]+'"></label><label>B<input type="number" min="0" max="255" data-rgb="2" value="'+rgb[2]+'"></label><label>'+T('Opacity','شفافية')+'<input type="range" min=".1" max="1" step=".05" data-color-opacity value="'+q.opacity+'"></label><button type="button" data-color-eye>◉ '+T('Eyedropper','قطّارة')+'</button><button type="button" data-color-reset>↺ '+T('Reset','إعادة ضبط')+'</button></div><div class="dcsp-shades">'+[-.5,-.25,0,.25,.5].map(function(f){var c=shade(p.drawColor,f);return'<button type="button" data-shade="'+c+'" style="background:'+c+'" title="'+c+'"></button>'}).join('')+'</div><div class="dcsp-project-paints"></div>';custom.appendChild(d);d.oninput=function(e){if(e.target.dataset.rgb!=null){var vals=[0,1,2].map(function(i){return d.querySelector('[data-rgb="'+i+'"]').value});p.drawColor=rgbHex(vals[0],vals[1],vals[2]);save()}if(e.target.matches('[data-color-opacity]')){q.opacity=Number(e.target.value);save()}};d.onclick=function(e){var s=e.target.dataset.shade;if(s){p.drawColor=s;save()}if(e.target.matches('[data-color-reset]')){p.drawColor='#dc2626';q.opacity=1;save();d.remove();enhanceColor(p)}if(e.target.matches('[data-color-eye]')&&window.EyeDropper)new EyeDropper().open().then(function(r){p.drawColor=r.sRGBHex;save()});var pc=e.target.dataset.projectPaint;if(pc){p.drawColor=pc;save()}};updateProjectColors(p)}
function updateProjectColors(p){var m=mounted[p.id],box=m&&m.page.querySelector('[data-project-colors]'),colors=defaults(p).projectColors||[];if(box){box.innerHTML=colors.map(function(c){return'<button class="dcsp-color-dot" data-color="'+esc(c)+'" title="'+esc(c)+'" style="background:'+esc(c)+'"></button>'}).join('');box.querySelectorAll('[data-color]').forEach(function(b){b.onclick=function(){p.drawColor=b.dataset.color;save()}})}var pb=m&&m.page.querySelector('.dcsp-project-paints');if(pb)pb.innerHTML=colors.map(function(c){return'<button type="button" data-project-paint="'+esc(c)+'" style="background:'+esc(c)+'" title="'+esc(c)+'"></button>'}).join('')}
function renderThumbs(force){var host=document.querySelector('#view-flange .dfp-index');if(!host)return;var old=host.querySelector('.dcsp-thumbstrip');if(old&&!force)return;if(old)old.remove();var strip=document.createElement('div');strip.className='dcsp-thumbstrip';(core().state.pages||[]).forEach(function(p,i){var b=document.createElement('button');b.className='dcsp-thumb'+(i===0?' active':'');b.draggable=true;b.dataset.thumb=p.id;b.innerHTML='<canvas width="104" height="64"></canvas><span>'+T('Page ','صفحة ')+(i+1)+'</span>';b.onclick=function(){var el=document.getElementById(p.id);if(el)el.scrollIntoView({behavior:'smooth',block:'start'})};strip.appendChild(b);var c=b.querySelector('canvas'),ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,104,64);defaults(p).objects.forEach(function(o){paintObj(ctx,o,p,104,64)})});strip.addEventListener('dragstart',function(e){var b=e.target.closest('[data-thumb]');if(b)e.dataTransfer.setData('text/plain',b.dataset.thumb)});strip.addEventListener('dragover',function(e){if(e.target.closest('[data-thumb]'))e.preventDefault()});strip.addEventListener('drop',function(e){var to=e.target.closest('[data-thumb]');if(!to)return;e.preventDefault();var id=e.dataTransfer.getData('text/plain'),pages=core().state.pages,si=pages.findIndex(function(p){return p.id===id}),ti=pages.findIndex(function(p){return p.id===to.dataset.thumb});if(si<0||ti<0||si===ti)return;var dir=si<ti?1:-1;while(si!==ti){var btn=document.querySelector('#view-flange .df-report[data-page="'+si+'"] [data-pro-action="page-'+(dir>0?'down':'up')+'"]');if(!btn)break;btn.click();si+=dir}});host.appendChild(strip)}
